parameters.functionCode:
// Check if results require immediate attention
const labData = items[0].json;
const criticalValues = {
  'glucose': { min: 70, max: 140 },
  'hemoglobin': { min: 12, max: 17 },
  'wbc': { min: 4.5, max: 11 }
};

labData.isCritical = false;
labData.criticalTests = [];

if (labData.results && typeof labData.results === 'object') {
  for (const [test, value] of Object.entries(labData.results)) {
    if (criticalValues[test]) {
      const range = criticalValues[test];
      if (value < range.min || value > range.max) {
        labData.isCritical = true;
        labData.criticalTests.push({
          test,
          value,
          range
        });
      }
    }
  }
}

return [{ json: labData }];

